50	static inline bool get_image_flag(int fd, int index)
51	{
52	  uint8_t flag;
53	  struct flash_partition_info info;
54	
55	  if (flash_partition_info(fd, &info) < 0)
56	    {
57	      return false;
58	    }
59	
60	  if (flash_partition_read(fd, &flag, 1,
61	                           info.size - info.blocksize * (index + 1)) < 0)
62	    {
63	      return false;
64	    }
65	
66	  return flag == 0xfe;
67	}
68	
69	static inline int set_image_flag(int fd, int index)
70	{
71	  uint8_t flag;
72	  struct flash_partition_info info;
73	
74	  if (flash_partition_info(fd, &info) < 0)
75	    {
76	      return ERROR;
77	    }
78	
79	  flag = 0xfe;
80	  return flash_partition_write(fd, &flag, 1,
81	                               info.size - (info.blocksize * (index + 1)));
82	}
83	
84	static inline void get_image_header(int fd, struct nxboot_img_header *header)
85	{
86	  int ret;
87	  ret = flash_partition_read(fd, header, sizeof *header, 0);
88	  if (ret < 0)
89	    {
90	      /* Something went wrong, treat the partition as empty. */
91	
92	      memset(header, 0, sizeof *header);
93	    }
94	}
95	
96	static inline bool validate_image_header(struct nxboot_img_header *header)
97	{
98	  return header->magic == NXBOOT_HEADER_MAGIC ||
99	         header->magic == NXBOOT_HEADER_MAGIC_INV;
100	}
101	
102	static uint32_t calculate_crc(int fd, struct nxboot_img_header *header)
103	{
104	  char *buf;
105	  int remain;
106	  int readsiz;
107	  off_t off;
108	  uint32_t crc;
109	  struct flash_partition_info info;
110	
111	  if (flash_partition_info(fd, &info) < 0)
112	    {
113	      return false;
114	    }
115	
116	  buf = malloc(info.blocksize);
117	  if (!buf)
118	    {
119	      return false;
120	    }
121	
122	  crc = 0xffffffff;
123	  remain = header->size;
124	  off = CONFIG_NXBOOT_HEADER_SIZE;
125	  while (remain > 0)
126	    {
127	      readsiz = remain > info.blocksize ? info.blocksize : remain;
128	      if (flash_partition_read(fd, buf, readsiz, off) != 0)
129	        {
130	          free(buf);
131	          return 0xffffffff;
132	        }
133	
134	      off += readsiz;
135	      remain -= readsiz;
136	      crc = crc32part((uint8_t *)buf, readsiz, crc);
137	    }
138	
139	  free(buf);
140	  return ~crc;
141	}
142	
143	static int copy_partition(int from, int where)
144	{
145	  struct nxboot_img_header header;
146	  struct flash_partition_info info_from;
147	  struct flash_partition_info info_where;
148	  uint32_t crc;
149	  uint32_t magic;
150	  int readsiz;
151	  int remain;
152	  int blocksize;
153	  off_t off;
154	  char *buf;
155	
156	  get_image_header(from, &header);
157	
158	  if (flash_partition_info(from, &info_from) < 0)
159	    {
160	      return ERROR;
161	    }
162	
163	  if (flash_partition_info(where, &info_where) < 0)
164	    {
165	      return ERROR;
166	    }
167	
168	  if ((header.size + CONFIG_NXBOOT_HEADER_SIZE) > info_where.size)
169	    {
170	      return ERROR;
171	    }
172	
173	  blocksize = MAX(info_from.blocksize, info_where.blocksize);
174	
175	  buf = malloc(blocksize);
176	  if (!buf)
177	    {
178	      return ERROR;
179	    }
180	
181	  if (flash_partition_erase_last_sector(where) < 0)
182	    {
183	      return ERROR;
184	    }
185	
186	  remain = header.size + CONFIG_NXBOOT_HEADER_SIZE;
187	  off = 0;
188	  if (header.magic == NXBOOT_HEADER_MAGIC_INV)
189	    {
190	      /* This means we are doing a recovery of a primary image
191	       * without the precalculated CRC. Calculate CRC and insert it
192	       * into the recovery image header. Also flip header's magic to
193	       * indicate this is an image with valid CRC.
194	       */
195	
196	      magic = NXBOOT_HEADER_MAGIC;
197	      crc = calculate_crc(from, &header);
198	      if (flash_partition_read(from, buf, blocksize, 0) < 0)
199	        {
200	          free(buf);
201	          return ERROR;
202	        }
203	
204	      memcpy(buf + offsetof(struct nxboot_img_header, magic), &magic,
205	             sizeof magic);
206	      memcpy(buf + offsetof(struct nxboot_img_header, crc), &crc,
207	             sizeof crc);
208	      if (flash_partition_write(where, buf, blocksize, 0) < 0)
209	        {
210	          free(buf);
211	          return ERROR;
212	        }
213	
214	      off += blocksize;
215	      remain -= blocksize;
216	    }
217	
218	  while (remain > 0)
219	    {
220	      readsiz = remain > blocksize ? blocksize : remain;
221	      if (flash_partition_read(from, buf, readsiz, off) < 0)
222	        {
223	          free(buf);
224	          return ERROR;
225	        }
226	
227	      if (flash_partition_write(where, buf, readsiz, off) < 0)
228	        {
229	          free(buf);
230	          return ERROR;
231	        }
232	
233	      off += readsiz;
234	      remain -= readsiz;
235	    }
236	
237	  if (header.magic != NXBOOT_HEADER_MAGIC_INV)
238	    {
239	      /* Copy currently set flags but only if the image has
240	       * precalculated CRC.
241	       */
242	
243	      if (get_image_flag(from, NXBOOT_UPDATED_PAGE_INDEX))
244	        {
245	          set_image_flag(where, NXBOOT_UPDATED_PAGE_INDEX);
246	        }
247	
248	      if (get_image_flag(from, NXBOOT_CONFIRMED_PAGE_INDEX))
249	        {
250	          set_image_flag(where, NXBOOT_CONFIRMED_PAGE_INDEX);
251	        }
252	    }
253	  else
254	    {
255	      set_image_flag(where, NXBOOT_CONFIRMED_PAGE_INDEX);
256	    }
257	
258	  free(buf);
259	  return OK;
260	}
261	
262	static bool validate_image(int fd)
263	{
264	  struct nxboot_img_header header;
265	
266	  get_image_header(fd, &header);
267	  if (!validate_image_header(&header))
268	    {
269	      return false;
270	    }
271	
272	  if (header.magic == NXBOOT_HEADER_MAGIC_INV)
273	    {
274	      /* Images with no precalculated CRC are considered valid. These
275	       * should be the images that are uploaded directly to the primary
276	       * paritition with debugger/flasher and are not uploaded by the
277	       * bootloader. These images also don't have confirmed flags,
278	       * altough they are considered stable.
279	       */
280	
281	      return true;
282	    }
283	  else
284	    {
285	      return calculate_crc(fd, &header) == header.crc;
286	    }
287	}
288	
289	static bool compare_versions(struct nxboot_img_version *v1,
290	                             struct nxboot_img_version *v2)
291	{
292	#ifndef CONFIG_NXBOOT_PREVENT_DOWNGRADE
293	  int i;
294	  if (v1->major != v2->major ||
295	      v1->minor != v2->minor ||
296	      v1->patch != v2->patch)
297	    {
298	      return false;
299	    }
300	
301	  for (i = 0; i < NXBOOT_HEADER_PRERELEASE_MAXLEN; i++)
302	    {
303	      if (v1->pre_release[i] != v2->pre_release[i])
304	        {
305	          return false;
306	        }
307	    }
308	
309	  return true;
310	#else
311	  if (v1->major > v2->major ||
312	      v1->minor > v2->minor ||
313	      v1->patch > v2->patch)
314	    {
315	      return true;
316	    }
317	
318	  if (v1->major == v2->major &&
319	      v1->minor == v2->minor &&
320	      v1->patch == v2->patch)
321	    {
322	      /* TODO: compare prerelease */
323	    }
324	
325	  return false;
326	#endif
327	}
