329	static enum nxboot_update_type
330	  get_update_type(int primary, int update, int recovery,
331	                  struct nxboot_img_header *primary_header,
332	                  struct nxboot_img_header *update_header)
333	{
334	  if (get_image_flag(recovery, NXBOOT_CONFIRMED_PAGE_INDEX) &&
335	      get_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX) &&
336	      ((!get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
337	      primary_header->magic != NXBOOT_HEADER_MAGIC_INV) ||
338	      !validate_image(primary)) && validate_image(recovery))
339	    {
340	      return NXBOOT_UPDATE_TYPE_REVERT;
341	    }
342	
343	  if (!get_image_flag(update, NXBOOT_CONFIRMED_PAGE_INDEX) &&
344	      !get_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX) &&
345	      validate_image(update))
346	    {
347	      if (compare_versions(&primary_header->img_version,
348	                           &update_header->img_version) &&
349	          validate_image(primary))
350	        {
351	          return NXBOOT_UPDATE_TYPE_NONE;
352	        }
353	
354	      return NXBOOT_UPDATE_TYPE_UPDATE;
355	    }
356	
357	  return NXBOOT_UPDATE_TYPE_NONE;
358	}
359	
360	static int perform_update(struct nxboot_state *state, bool check_only)
361	{
362	  int update;
363	  int recovery;
364	  int primary;
365	  int secondary;
366	  int tertiary;
367	  bool primary_valid;
368	
369	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
370	  assert(primary >= 0);
371	
372	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
373	  assert(secondary >= 0);
374	
375	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
376	  assert(tertiary >= 0);
377	
378	  if (state->update == NXBOOT_SECONDARY_SLOT_NUM)
379	    {
380	      update = secondary;
381	      recovery = tertiary;
382	    }
383	  else
384	    {
385	      update = tertiary;
386	      recovery = secondary;
387	    }
388	
389	  if (state->next_boot == NXBOOT_UPDATE_TYPE_REVERT &&
390	      (!check_only || !validate_image(primary)))
391	    {
392	      if (validate_image(recovery))
393	        {
394	          syslog(LOG_INFO, "Reverting image to recovery.\n");
395	          copy_partition(recovery, primary);
396	        }
397	    }
398	  else
399	    {
400	      primary_valid = validate_image(primary);
401	      if (primary_valid && check_only)
402	        {
403	          /* Skip if primary image is valid (does not mather whether
404	           * confirmed or not) and check_only option is set.
405	           */
406	
407	          goto perform_update_done;
408	        }
409	
410	      if (!state->recovery_valid && state->primary_confirmed &&
411	          primary_valid)
412	        {
413	          /* Save current image as recovery only if it is valid and
414	           * confirmed. We have to check this in case of restart
415	           * during update process.
416	           * If board is restarted during update, primary slot contains
417	           * non-valid image and we do not want to copy this image to
418	           * recovery slot.
419	           * There also might be a case where primary image is valid
420	           * but not confirmed (timing of board reset right after
421	           * update is uploaded to secondary). Still we do not want
422	           * to upload this to recovery.
423	           */
424	
425	          syslog(LOG_INFO, "Creating recovery image.\n");
426	          copy_partition(primary, recovery);
427	          if (!validate_image(recovery))
428	            {
429	              syslog(LOG_INFO, "New recovery is not valid, stop update\n");
430	              goto perform_update_done;
431	            }
432	
433	          syslog(LOG_INFO, "Recovery image created.\n");
434	        }
435	
436	      if (validate_image(update))
437	        {
438	          /* Perform update only if update slot contains valid image. */
439	
440	          syslog(LOG_INFO, "Updating from update image.\n");
441	          copy_partition(update, primary);
442	
443	          /* Mark update slot as updated. This is to prevent repeated
444	           * updates.
445	           */
446	
447	          set_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX);
448	        }
449	    }
450	
451	perform_update_done:
452	  flash_partition_close(primary);
453	  flash_partition_close(secondary);
454	  flash_partition_close(tertiary);
455	  return OK;
456	}
