458	/****************************************************************************
459	 * Public Functions
460	 ****************************************************************************/
461	
462	/****************************************************************************
463	 * Name: nxboot_get_state
464	 *
465	 * Description:
466	 *   Gets the current bootloader state and stores it in the nxboot_state
467	 *   structure passed as an argument. This function may be used to determine
468	 *   which slot is update slot and where should application save incoming
469	 *   firmware.
470	 *
471	 * Input parameters:
472	 *   state: The pointer to nxboot_state structure. The state is stored here.
473	 *
474	 * Returned Value:
475	 *   0 on success, -1 and sets errno on failure.
476	 *
477	 ****************************************************************************/
478	
479	int nxboot_get_state(struct nxboot_state *state)
480	{
481	  int primary;
482	  int secondary;
483	  int tertiary;
484	  int update;
485	  int recovery;
486	  struct nxboot_img_header primary_header;
487	  struct nxboot_img_header secondary_header;
488	  struct nxboot_img_header tertiary_header;
489	  struct nxboot_img_header *update_header;
490	
491	  memset(state, 0, sizeof *state);
492	
493	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
494	  if (primary < 0)
495	    {
496	      return ERROR;
497	    }
498	
499	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
500	  if (secondary < 0)
501	    {
502	      flash_partition_close(primary);
503	      return ERROR;
504	    }
505	
506	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
507	  if (tertiary < 0)
508	    {
509	      flash_partition_close(primary);
510	      flash_partition_close(secondary);
511	      return ERROR;
512	    }
513	
514	  get_image_header(primary, &primary_header);
515	  get_image_header(secondary, &secondary_header);
516	  get_image_header(tertiary, &tertiary_header);
517	
518	  update = secondary;
519	  recovery = tertiary;
520	  update_header = &secondary_header;
521	  state->update = NXBOOT_SECONDARY_SLOT_NUM;
522	  state->recovery = NXBOOT_TERTIARY_SLOT_NUM;
523	  if (get_image_flag(secondary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
524	      validate_image(secondary))
525	    {
526	      /* Secondary image is confirmed and valid, use this as
527	       * a potential recovery.
528	       */
529	
530	      update = tertiary;
531	      recovery = secondary;
532	      state->recovery = NXBOOT_SECONDARY_SLOT_NUM;
533	      state->update = NXBOOT_TERTIARY_SLOT_NUM;
534	      update_header = &tertiary_header;
535	
536	      if (secondary_header.crc == primary_header.crc)
537	        {
538	          state->recovery_valid = true;
539	        }
540	    }
541	  else if (get_image_flag(tertiary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
542	           tertiary_header.crc == primary_header.crc &&
543	           validate_image(tertiary))
544	    {
545	      state->recovery_valid = true;
546	    }
547	
548	  if (get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) ||
549	      primary_header.magic == NXBOOT_HEADER_MAGIC_INV)
550	    {
551	      state->primary_confirmed = true;
552	    }
553	
554	  state->next_boot = get_update_type(primary, update, recovery,
555	                                     &primary_header, update_header);
556	
557	  flash_partition_close(primary);
558	  flash_partition_close(secondary);
559	  flash_partition_close(tertiary);
560	  return OK;
561	}
