563	/****************************************************************************
564	 * Name: nxboot_get_confirm
565	 *
566	 * Description:
567	 *   This function can be used to determine whether primary image is
568	 *   confirmed or not. This provides more direct access to confirm
569	 *   state compared to nxboot_get_state function that returns the full
570	 *   state of the bootloader.
571	 *
572	 * Returned Value:
573	 *   1 means confirmed, 0 not confirmed, -1 and sets errno on failure.
574	 *
575	 ****************************************************************************/
576	
577	int nxboot_get_confirm(void)
578	{
579	  int primary;
580	  struct nxboot_img_header primary_header;
581	
582	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
583	  if (primary < 0)
584	    {
585	      return ERROR;
586	    }
587	
588	  get_image_header(primary, &primary_header);
589	  if (get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) ||
590	      primary_header.magic == NXBOOT_HEADER_MAGIC_INV)
591	    {
592	      return 1;
593	    }
594	
595	  return 0;
596	}
597	
598	/****************************************************************************
599	 * Name: nxboot_confirm
600	 *
601	 * Description:
602	 *   Confirms the image currently located in primary partition and marks
603	 *   its copy in update partition as a recovery.
604	 *
605	 * Returned Value:
606	 *   0 on success, -1 and sets errno on failure.
607	 *
608	 ****************************************************************************/
609	
610	int nxboot_confirm(void)
611	{
612	  int ret;
613	  int update;
614	  int primary;
615	  int secondary;
616	  int tertiary;
617	  int recovery;
618	  struct nxboot_state state;
619	
620	  nxboot_get_state(&state);
621	  if (state.primary_confirmed)
622	    {
623	      return OK;
624	    }
625	
626	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
627	  if (primary < 0)
628	    {
629	      return ERROR;
630	    }
631	
632	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
633	  if (secondary < 0)
634	    {
635	      flash_partition_close(primary);
636	      return ERROR;
637	    }
638	
639	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
640	  if (tertiary < 0)
641	    {
642	      flash_partition_close(primary);
643	      flash_partition_close(secondary);
644	      return ERROR;
645	    }
646	
647	  if (state.update == NXBOOT_SECONDARY_SLOT_NUM)
648	    {
649	      update = secondary;
650	      recovery = tertiary;
651	    }
652	  else
653	    {
654	      update = tertiary;
655	      recovery = secondary;
656	    }
657	
658	  /* We need to mark both primary and update partitions as confirmed
659	   * (update partition will become recovery once confirmed) and
660	   * we have to remove confirmed flag from old recovery and set updated
661	   * flag there. This is to prevent old recovery still identify as
662	   * recovery and not to look as possible update. Therefore remove the
663	   * entire last sector (clears confirmed flag) and write updated
664	   * flag.
665	   */
666	
667	  ret = OK;
668	  if (set_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) < 0)
669	    {
670	      ret = ERROR;
671	      goto confirm_done;
672	    }
673	
674	  if (set_image_flag(update, NXBOOT_CONFIRMED_PAGE_INDEX) < 0)
675	    {
676	      ret = ERROR;
677	      goto confirm_done;
678	    }
679	
680	  if (flash_partition_erase_last_sector(recovery) < 0)
681	    {
682	      ret = ERROR;
683	      goto confirm_done;
684	    }
685	
686	  if (set_image_flag(recovery, NXBOOT_UPDATED_PAGE_INDEX) < 0)
687	    {
688	      ret = ERROR;
689	      goto confirm_done;
690	    }
691	
692	confirm_done:
693	  flash_partition_close(primary);
694	  flash_partition_close(secondary);
695	  flash_partition_close(tertiary);
696	
697	  return ret;
698	}
