700	/****************************************************************************
701	 * Name: nxboot_perform_update
702	 *
703	 * Description:
704	 *   Checks for the possible firmware update and performs it by copying
705	 *   update image to primary slot or recovery image to primary slot in case
706	 *   of the revert. In any situation, this function ends with the valid
707	 *   image in primary slot.
708	 *
709	 *   This is an entry point function that should be called from the
710	 *   bootloader application.
711	 *
712	 * Input parameters:
713	 *   check_only: Only repairs corrupted update, but do not start another one
714	 *
715	 * Returned Value:
716	 *   0 on success, -1 and sets errno on failure.
717	 *
718	 ****************************************************************************/
719	
720	int nxboot_perform_update(bool check_only)
721	{
722	  int ret;
723	  struct nxboot_state state;
724	
725	  ret = nxboot_get_state(&state);
726	  if (ret < 0)
727	    {
728	      return ERROR;
729	    }
730	
731	  if (state.next_boot != NXBOOT_UPDATE_TYPE_NONE)
732	    {
733	      /* We either want to update or revert. */
734	
735	      ret = perform_update(&state, check_only);
736	      if (ret < 0)
737	        {
738	          syslog(LOG_ERR, "Update process failed. %s\n",
739	             strerror(errno));
740	        }
741	    }
742	
743	  return ret;
744	}
