46	/****************************************************************************
47	 * Name: flash_partition_open
48	 *
49	 * Description:
50	 *   Opens the partition based on a given name and returns the file
51	 *   descriptor to it.
52	 *
53	 * Input parameters:
54	 *   path: Path to the device.
55	 *
56	 * Returned Value:
57	 *   Valid file descriptor on success, -1 on failure.
58	 *
59	 ****************************************************************************/
60	
61	int flash_partition_open(const char *path)
62	{
63	  int fd;
64	
65	  fd = open(path, O_RDWR);
66	  if (fd < 0)
67	    {
68	      syslog(LOG_ERR, "Could not open %s partition: %s\n",
69	              path, strerror(errno));
70	      return ERROR;
71	    }
72	
73	  return fd;
74	}
