95	/****************************************************************************
96	 * Name: flash_partition_write
97	 *
98	 * Description:
99	 *   Writes count data pointed to by buf at offset off to a partition
100	 *   referenced by file descriptor fd.
101	 *
102	 * Input parameters:
103	 *   fd: Valid file descriptor.
104	 *   buf: The pointer to data to be written.
105	 *   count: Number of bytes to be written.
106	 *   off: Write offset in bytes.
107	 *
108	 * Returned Value:
109	 *   0 on success, -1 on failure.
110	 *
111	 ****************************************************************************/
112	
113	int flash_partition_write(int fd, const void *buf, size_t count, off_t off)
114	{
115	  int ret;
116	  off_t pos;
117	  size_t size;
118	  ssize_t nbytes;
119	  struct mtd_geometry_s geometry;
120	
121	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&geometry));
122	  if (ret < 0)
123	    {
124	      syslog(LOG_ERR, "ioctl MTDIOC_GEOMETRY failed: %s\n", strerror(errno));
125	      return ERROR;
126	    }
127	
128	  size = geometry.erasesize * geometry.neraseblocks;
129	  if (count + off > size)
130	    {
131	      syslog(LOG_ERR, "Trying to write outside of flash area.\n");
132	      return ERROR;
133	    }
134	
135	  pos = lseek(fd, off, SEEK_SET);
136	  if (pos != off)
137	    {
138	      syslog(LOG_ERR, "Could not seek to %ld: %s\n", off, strerror(errno));
139	      return ERROR;
140	    }
141	
142	  nbytes = write(fd, buf, count);
143	  if (nbytes != count)
144	    {
145	      syslog(LOG_ERR, "Write to offset %ld failed %s\n",
146	              off, strerror(errno));
147	      return ERROR;
148	    }
149	
150	  return OK;
151	}
152	
153	/****************************************************************************
154	 * Name: flash_partition_read
155	 *
156	 * Description:
157	 *   Read count data to buffer buf at offset off from a partition
158	 *   referenced by file descriptor fd.
159	 *
160	 * Input parameters:
161	 *   fd: Valid file descriptor.
162	 *   buf: The pointer where read data are stored.
163	 *   count: Number of bytes to be read.
164	 *   off: Read offset in bytes.
165	 *
166	 * Returned Value:
167	 *   0 on success, -1 on failure.
168	 *
169	 ****************************************************************************/
170	
171	int flash_partition_read(int fd, void *buf, size_t count, off_t off)
172	{
173	  int ret;
174	  off_t pos;
175	  size_t size;
176	  ssize_t nbytes;
177	  struct mtd_geometry_s geometry;
178	
179	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&geometry));
180	  if (ret < 0)
181	    {
182	      syslog(LOG_ERR, "ioctl MTDIOC_GEOMETRY failed: %s\n", strerror(errno));
183	      return ERROR;
184	    }
185	
186	  size = geometry.erasesize * geometry.neraseblocks;
187	  if (count + off > size)
188	    {
189	      syslog(LOG_ERR, "Trying to read outside of flash area.\n");
190	      return ERROR;
191	    }
192	
193	  pos = lseek(fd, off, SEEK_SET);
194	  if (pos != off)
195	    {
196	      syslog(LOG_ERR, "Could not seek to %ld: %s\n", off, strerror(errno));
197	      return ERROR;
198	    }
199	
200	  nbytes = read(fd, buf, count);
201	  if (nbytes != count)
202	    {
203	      syslog(LOG_ERR, "Read from offset %ld failed %s\n",
204	              off, strerror(errno));
205	      return ERROR;
206	    }
207	
208	  return OK;
209	}
