211	/****************************************************************************
212	 * Name: flash_partition_erase
213	 *
214	 * Description:
215	 *   Erases the entire partition.
216	 *
217	 * Input parameters:
218	 *   fd: Valid file descriptor.
219	 *
220	 * Returned Value:
221	 *   0 on success, -1 on failure.
222	 *
223	 ****************************************************************************/
224	
225	int flash_partition_erase(int fd)
226	{
227	  int ret;
228	
229	  ret = ioctl(fd, MTDIOC_BULKERASE, 0);
230	  if (ret < 0)
231	    {
232	      syslog(LOG_ERR, "Could not erase the partition: %s\n",
233	              strerror(errno));
234	      return ERROR;
235	    }
236	
237	  return OK;
238	}
239	
240	/****************************************************************************
241	 * Name: flash_partition_erase_last_sector
242	 *
243	 * Description:
244	 *   Erases the last sector of the partition
245	 *
246	 * Input parameters:
247	 *   fd: Valid file descriptor.
248	 *
249	 * Returned Value:
250	 *   0 on success, -1 on failure.
251	 *
252	 ****************************************************************************/
253	
254	int flash_partition_erase_last_sector(int fd)
255	{
256	  int ret;
257	  struct mtd_erase_s erase;
258	  struct flash_partition_info info;
259	
260	  if (flash_partition_info(fd, &info) < 0)
261	    {
262	      return ERROR;
263	    }
264	
265	  erase.startblock = info.neraseblocks - 1;
266	  erase.nblocks = 1;
267	
268	  ret = ioctl(fd, MTDIOC_ERASESECTORS, &erase);
269	  if (ret < 0)
270	    {
271	      syslog(LOG_ERR, "Could not erase the partition: %s\n",
272	              strerror(errno));
273	      return ERROR;
274	    }
275	
276	  return OK;
277	}
278	
279	/****************************************************************************
280	 * Name: flash_partition_info
281	 *
282	 * Description:
283	 *   Returns the size of one block.
284	 *
285	 * Input parameters:
286	 *   fd: Valid file descriptor.
287	 *   info: Pointer to flash_partition_info structure where info is filled.
288	 *
289	 * Returned Value:
290	 *   Size of the block on success, -1 on failure.
291	 *
292	 ****************************************************************************/
293	
294	int flash_partition_info(int fd, struct flash_partition_info *info)
295	{
296	  int ret;
297	  struct mtd_geometry_s geometry;
298	
299	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&geometry));
300	  if (ret < 0)
301	    {
302	      syslog(LOG_ERR, "ioctl MTDIOC_GEOMETRY failed: %s\n", strerror(errno));
303	      return ERROR;
304	    }
305	
306	  info->blocksize = geometry.blocksize;
307	  info->size = geometry.erasesize * geometry.neraseblocks;
308	  info->neraseblocks = geometry.neraseblocks;
309	
310	  return OK;
311	}
