488	/****************************************************************************
489	 * Name: board_early_initialize
490	 *
491	 * Description:
492	 *   If CONFIG_BOARD_EARLY_INITIALIZE is selected, then an additional
493	 *   initialization call will be performed in the boot-up sequence to a
494	 *   function called board_early_initialize().  board_early_initialize()
495	 *   will be called immediately after up_initialize() and well before
496	 *   board_early_initialize() is called and the initial application is
497	 *   started.  The context in which board_early_initialize() executes is
498	 *   suitable for early initialization of most, simple device drivers and
499	 *   is a logical, board-specific extension of up_initialize().
500	 *
501	 *   board_early_initialize() runs on the startup, initialization thread.
502	 *   Some initialization operations cannot be performed on the start-up,
503	 *   initialization thread.  That is because the initialization thread
504	 *   cannot wait for event.  Waiting may be required, for example, to
505	 *   mount a file system or or initialize a device such as an SD card.
506	 *   For this reason, such driver initialize must be deferred to
507	 *   board_late_initialize().
508	
509	 ****************************************************************************/
510	
511	#ifdef CONFIG_BOARD_EARLY_INITIALIZE
512	void board_early_initialize(void)
513	{
514	
515	}
516	#endif
517	
518	/****************************************************************************
519	 * Name: board_late_initialize
520	 *
521	 * Description:
522	 *   If CONFIG_BOARD_LATE_INITIALIZE is selected, then an additional
523	 *   initialization call will be performed in the boot-up sequence to a
524	 *   function called board_late_initialize().  board_late_initialize() will
525	 *   be called after up_initialize() and board_early_initialize() and just
526	 *   before the initial application is started.  This additional
527	 *   initialization phase may be used, for example, to initialize board-
528	 *   specific device drivers for which board_early_initialize() is not
529	 *   suitable.
530	 *
531	 *   Waiting for events, use of I2C, SPI, etc are permissible in the context
532	 *   of board_late_initialize().  That is because board_late_initialize()
533	 *   will run on a temporary, internal kernel thread.
534	 *
535	 ****************************************************************************/
536	
537	#ifdef CONFIG_BOARD_LATE_INITIALIZE
538	void board_late_initialize(void)
539	{
540	  /* Perform board-specific initialization */
541	
542	  sf32lb58_lcd_bringup();
543	}
544	#endif
545	
546	/****************************************************************************
547	 * Name: board_app_initialize
548	 *
549	 * Description:
550	 *   Perform application specific initialization.  This function is never
551	 *   called directly from application code, but only indirectly via the
552	 *   (non-standard) boardctl() interface using the command BOARDIOC_INIT.
553	 *
554	 * Input Parameters:
555	 *   arg - The boardctl() argument is passed to the board_app_initialize()
556	 *         implementation without modification.  The argument has no
557	 *         meaning to NuttX; the meaning of the argument is a contract
558	 *         between the board-specific initialization logic and the
559	 *         matching application logic.  The value could be such things as a
560	 *         mode enumeration value, a set of DIP switch settings, a
561	 *         pointer to configuration data read from a file or serial FLASH,
562	 *         or whatever you would like to do with it.  Every implementation
563	 *         should accept zero/NULL as a default configuration.
564	 *
565	 * Returned Value:
566	 *   Zero (OK) is returned on success; a negated errno value is returned on
567	 *   any failure to indicate the nature of the failure.
568	 *
569	 ****************************************************************************/
570	
571	int board_app_initialize(uintptr_t arg)
572	{
573	#ifdef CONFIG_BOARD_LATE_INITIALIZE
574	  /* Board initialization already performed by board_late_initialize() */
575	
576	  return OK;
577	#else
578	  /* Perform board-specific initialization */
579	
580	  return sf32lb58_lcd_bringup();
581	#endif
582	}
583	
584	#ifdef CONFIG_BOARDCTL_RESET
585	int board_reset(int status)
586	{
587	  (void)status;
588	
589	  up_systemreset();
590	  return OK;
591	}
592	#endif
593	
594	/****************************************************************************
595	 * Name: board_app_finalinitialize
596	 *
597	 * Description:
598	 *   Perform application specific initialization.  This function is never
599	 *   called directly from application code, but only indirectly via the
600	 *   (non-standard) boardctl() interface using the command
601	 *   BOARDIOC_FINALINIT.
602	 *
603	 * Input Parameters:
604	 *   arg - The argument has no meaning.
605	 *
606	 * Returned Value:
607	 *   Zero (OK) is returned on success; a negated errno value is returned on
608	 *   any failure to indicate the nature of the failure.
609	 *
610	 ****************************************************************************/
611	
612	#ifdef CONFIG_BOARDCTL_FINALINIT
613	int board_app_finalinitialize(uintptr_t arg)
614	{
615	  return 0;
616	}
617	#endif
