21	/* SF32LB58 a128r32n1 memory layout (migrated to openvela NuttX):
22	 *
23	 *   Flash (XIP):  QSPI2 NOR 1 MB at 0x12000000 (bootloader @ 0x12000000, app @ 0x12010000)
24	 *   SRAM:         RAM0-RAM5 = 1.5 MB (0x20000000 - 0x20180000)
25	 *   PSRAM:        MPI1 OPSRAM = 32 MB (0x60200000, after 2MB reserved)
26	 *
27	 * Migration notes (sf32lb52 SDK → openvela pattern):
28	 *   - Removed: .retm_data, .itcm_code/.itcm_data, .retm_bss/.itcm_bss,
29	 *              .RW_IRAM0, .rom_ex, .rom2/.rom3, .stack/.heap, ROM_EX/ROM2/ROM3
30	 *   - Added:   .ramfunc (flash driver), .ram_vectors, .tdata/.tbss,
31	 *              /DISCARD/ build-id, NuttX startup symbols
32	 *   - .ramfunc covers critical code that must run from SRAM (flash erase/write)
33	 */
34	
35	MEMORY
36	{
37	  rom (rx)  : ORIGIN = 0x10000000, LENGTH = 4M     /* 4MB occupied for code */
38	  sram (rwx)  : ORIGIN = 0x20000000, LENGTH = 1536K    /* RAM0-RAM5: 128+128+256+512+512 KB */
39	  retention_ram (rw) : ORIGIN = 0x00020000, LENGTH = 64K
40	  psram (rwx) : ORIGIN = 0x60400000, LENGTH = 16M      /* MPI1 qPSRAM, after 4MB reserved for code */
41	  psram2 (rwx) : ORIGIN = 0x62000000, LENGTH = 16M      /* MPI2 qPSRAM */
42	}
